with with_latest as (select s.id, s.dept_name, s.location, s.budget, latest.employee_hire_date from departments s left join lateral (select c.hire_date as employee_hire_date from employees c where c.dept_id = s.id order by c.salary desc, c.id desc limit 1) latest on true) select date_trunc('month', employee_hire_date) as activity_month, count(*) filter (where dept_name = 'Sales') as sales_rows, count(distinct dept_name) as distinct_dept_names, size(collect_set(location)) as num_locations, sum(budget) filter (where location = 'Chiang Mai') as chiang_mai_total_budget, count(case when dept_name = 'HR' then 1 end) as hr_count, round(avg(budget), 2) as avg_budget from with_latest group by date_trunc('month', employee_hire_date) order by hr_count desc
